  // ---------------- daily financials ----------------
  let MRR0 = null;
  function daily(r, d, dow, ago) {
    if (MRR0 == null) MRR0 = (S() && S().customers) ? mrr() : 11800;
    const grow = 1 - 0.18 * Math.min(ago, 400) / 365;
    const checkins = Math.round(CI_DOW[dow] * SEASON[d.getMonth()] * (0.86 + r() * 0.28) * (1 - 0.1 * Math.min(ago, 400) / 365));
    const dues = MRR0 * grow / 30.4; const pt = dow === 0 ? 0 : 90 + r() * 220; const retail = 40 + r() * 160; const passes = r() < 0.6 ? 20 + r() * 80 : 0;
    const rev = dues + pt + retail + passes;
    return { rev, checkins, dues, pt, retail, passes, cogs: retail * 0.55 + 12, labor: 150 + pt * 0.45, other: 140 + r() * 30 };
  }

